import re
from wordfreq import word_frequency

def _extract_bigrams(text):
    pattern = r"[a-zA-Z']+"
    words = [w.lower() for w in re.findall(pattern, text or '')]
    return [tuple(words[i:i+2]) for i in range(len(words)-1)]

def formulaic_bigram_avoidance(text, anchor):
    anchor_bigrams = _extract_bigrams(anchor)
    text_bigrams_set = set(_extract_bigrams(text))

    if not anchor_bigrams:
        return 0.5

    avoided_count = sum(1 for bg in anchor_bigrams if bg not in text_bigrams_set)
    score = avoided_count / len(anchor_bigrams)

    return max(0.0, min(1.0, score))

METRICS = {'formulaic_bigram_avoidance': formulaic_bigram_avoidance}
